  history: {enabled: boolean} | undefined,
  limit?: number,
  before?: SessionListOptions['before']
): Promise<void> {
  if (!history?.enabled) {
    sendError(ws, ErrorCodes.UNSUPPORTED, 'History is not enabled');
    return;
  }

  if (!sessionStore.listFor) {
    sendError(ws, ErrorCodes.UNSUPPORTED, 'Store does not support listing sessions');
    return;
  }

  try {
    const summaries = await sessionStore.listFor(session.userId, {limit, before});
    const frames: SessionSummaryFrame[] = summaries.map(s => ({
      sessionId: s.sessionId,
      createdAt: s.createdAt.toISOString(),
      updatedAt: s.updatedAt.toISOString(),
      entryCount: s.entryCount,
    }));
    sendSessionList(ws, frames);
  } catch (error) {
    if (error instanceof StoreCannotList) {
      sendError(ws, ErrorCodes.UNSUPPORTED, error.message);
      return;
    }
    const message = error instanceof Error ? error.message : 'Unknown error';
    log.error('ws', 'failed to list sessions', {sessionId: session.sessionId, userId: session.userId, error: message});
    sendError(ws, ErrorCodes.SERVER_ERROR, 'Failed to list sessions');
  }
}

/** Resolves when the check returns true, or after 500ms. */
export const eventually = async (check: () => boolean): Promise<void> => {
  for (let attempt = 0; attempt < 50 && !check(); attempt++) await new Promise(resolve => setTimeout(resolve, 10));
};

